class LmdbNoneAdmissionDeadlineTest {

	private static final String SEED_SUBJECT = "urn:lmdb:none-admission:seed";
	private static final String SEED_PREDICATE = "urn:lmdb:none-admission:predicate";
	private static final String SEED_OBJECT = "urn:lmdb:none-admission:value";
	private static final String GROWTH_PREDICATE = "urn:lmdb:none-admission:growth";
	private static final String TIMEOUT_MESSAGE = "Query evaluation took too long";
	private static final long INITIAL_MAP_BYTES = 64L * 1024L * 1024L;
	private static final int MAX_GROWTH_ROWS = 50_000;
	private static final long WAIT_SECONDS = 20L;

	@ParameterizedTest
	@EnumSource(QueryKind.class)
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void repositoryQueryTimesOutWhileNoneWriterHoldsGrowthAdmission(QueryKind kind, @TempDir Path dataDirectory)
			throws Exception {
		LmdbStore store = newStore(dataDirectory);
		SailRepository repository = new SailRepository(store);
		ExecutorService queryExecutor = Executors.newSingleThreadExecutor();
		ExecutorService writerExecutor = Executors.newSingleThreadExecutor();
		CountDownLatch queryPrepared = new CountDownLatch(1);
		CountDownLatch startQuery = new CountDownLatch(1);
		CountDownLatch queryEvaluationStarted = new CountDownLatch(1);
		CountDownLatch writerHoldingGrowth = new CountDownLatch(1);
		CountDownLatch releaseWriter = new CountDownLatch(1);
		Future<Boolean> queryFuture = null;
		Future<?> writerFuture = null;
		try {
			repository.init();
			LmdbSailStore backing = store.getBackingStore();
			try (RepositoryConnection seed = repository.getConnection()) {
				seed.add(Values.iri(SEED_SUBJECT), Values.iri(SEED_PREDICATE), Values.literal(SEED_OBJECT));
			}

			queryFuture = queryExecutor.submit(() -> {
				try (RepositoryConnection reader = repository.getConnection()) {
					Query query = prepareQuery(reader, kind);
					query.setMaxExecutionTime(1);
					queryPrepared.countDown();
					await(startQuery, "the test must start the prepared public query");
					queryEvaluationStarted.countDown();
					return evaluateQuery(query);
				}
			});
			assertTrue(queryPrepared.await(5, TimeUnit.SECONDS),
					"the public repository query must be prepared before the NONE writer starts");

			MapGrowthMetrics.Snapshot before = backing.growthMetricsSnapshot();
			writerFuture = writerExecutor.submit(() -> {
				try (RepositoryConnection writer = repository.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.setNamespace("growth-demand", growthNamespace());
					for (int index = 0; index < MAX_GROWTH_ROWS; index++) {
						writer.add(Values.iri("urn:lmdb:none-admission:growth:" + index),
								Values.iri(GROWTH_PREDICATE), Values.literal("growth-value"));
						if (backing.growthAdmissionClosed()) {
							writerHoldingGrowth.countDown();
							await(releaseWriter, "the test must release the NONE writer after the query deadline");
							writer.rollback();
							return null;
						}
					}
					throw new AssertionError("the real NONE write demand did not close growth admission");
				}
			});

			assertTrue(writerHoldingGrowth.await(15, TimeUnit.SECONDS),
					"authoritative soft map demand must close admission while the NONE transaction remains active");
			awaitPhase(backing, LmdbSailStore.GrowthPhase.DRAIN_WRITERS,
					"the active NONE transaction must hold the growth coordinator in writer drain");
			MapGrowthMetrics.Snapshot waiting = backing.growthMetricsSnapshot();
			startQuery.countDown();
			assertTrue(queryEvaluationStarted.await(3, TimeUnit.SECONDS),
					"the query evaluation must enter on its worker");
			Future<Boolean> waitingQuery = queryFuture;
			awaitAdmissionWait(backing, waiting.admissionWaitCount(), queryFuture,
					"the query must reach the closed growth-admission wait");

			ExecutionException timeout = assertThrows(ExecutionException.class,
					() -> waitingQuery.get(4, TimeUnit.SECONDS),
					"the public query deadline must expire before the held writer is released");
			Throwable cause = rootCause(timeout);
			assertEquals(QueryInterruptedException.class, cause.getClass());
			assertEquals(TIMEOUT_MESSAGE, cause.getMessage());
			MapGrowthMetrics.Snapshot timedOut = backing.growthMetricsSnapshot();
			assertTrue(timedOut.admissionWaitCount() > waiting.admissionWaitCount(),
					"the query must time out from the real map-growth admission wait");
			assertTrue(timedOut.admissionTimeouts() > waiting.admissionTimeouts(),
					"the query's scoped deadline must be recorded as an admission timeout");
			assertEquals(waiting.currentAdmissionWaiters(), timedOut.currentAdmissionWaiters(),
					"the timed-out query must leave no growth-admission waiter behind");
			assertEquals(waiting.growthEpisodes(), timedOut.growthEpisodes(),
					"timing out one query must not abort or replace the writer's shared growth episode");
			assertEquals(waiting.emergencyFailures(), timedOut.emergencyFailures(),
					"query cancellation must not turn soft growth into an emergency failure");
			assertEquals(LmdbSailStore.GrowthPhase.DRAIN_WRITERS, timedOut.currentPhase(),
					"the NONE writer must still own the active growth episode after query cancellation");
			assertTrue(backing.growthAdmissionClosed(),
					"query cancellation must not reopen admission ahead of the writer");
			assertFalse(writerFuture.isDone(),
					"the test still holds the NONE writer until after the deadline assertion");

			releaseWriter.countDown();
			writerFuture.get(WAIT_SECONDS, TimeUnit.SECONDS);
			writerFuture = null;
			awaitGrowthReopened(backing);
			try (RepositoryConnection recovered = repository.getConnection()) {
				assertTrue(evaluateQuery(prepareQuery(recovered, kind)),
						"a fresh public query must succeed after the NONE writer rolls back and growth completes");
			}
		} finally {
			releaseWriter.countDown();
			awaitIfPresent(writerFuture);
			awaitIfPresent(queryFuture);
			queryExecutor.shutdownNow();
			writerExecutor.shutdownNow();
			try {
				assertTrue(queryExecutor.awaitTermination(5, TimeUnit.SECONDS), "the query worker must terminate");
				assertTrue(writerExecutor.awaitTermination(5, TimeUnit.SECONDS), "the writer worker must terminate");
			} finally {
				repository.shutDown();
			}
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void scopedSnapshotBeginTimesOutBehindAnOpenNoneIsolationLock(@TempDir Path dataDirectory) throws Exception {
		LmdbStore store = newStore(dataDirectory);
		SailRepository repository = new SailRepository(store);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch beginStarted = new CountDownLatch(1);
		Future<BeginAttempt> beginFuture = null;
		try {
			repository.init();
			LmdbSailStore backing = store.getBackingStore();
			try (RepositoryConnection noneOwner = repository.getConnection()) {
				noneOwner.begin(IsolationLevels.NONE);
				assertFalse(backing.growthAdmissionClosed(),
						"the transaction-lock case must begin with map-growth admission open");
				beginFuture = executor.submit(() -> {
					try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1_000L);
							QueryExecutionDeadline.Scope ignored = deadline.enter();
							RepositoryConnection waiting = repository.getConnection()) {
						beginStarted.countDown();
						Throwable failure = null;
						try {
							waiting.begin(IsolationLevels.SNAPSHOT);
						} catch (Throwable beginFailure) {
							failure = beginFailure;
						}
						boolean activeAfterBegin = waiting.isActive();
						if (activeAfterBegin) {
							waiting.rollback();
						}
						return new BeginAttempt(failure, activeAfterBegin);
					}
				});
				assertTrue(beginStarted.await(2, TimeUnit.SECONDS),
						"the worker must enter the scoped transaction begin while NONE is active");

				BeginAttempt result = beginFuture.get(3, TimeUnit.SECONDS);
				assertNotNull(result.failure(), "the scoped snapshot begin must time out behind the NONE lock");
				Throwable cause = rootCause(result.failure());
				assertEquals(QueryInterruptedException.class, cause.getClass());
				assertEquals(TIMEOUT_MESSAGE, cause.getMessage());
				assertFalse(result.activeAfterBegin(),
						"a timed-out begin must not leak a partially active transaction");
				assertTrue(noneOwner.isActive(), "the timeout must leave the lock-owning NONE transaction intact");
				assertFalse(backing.growthAdmissionClosed(), "transaction-lock waiting must not start map growth");

				noneOwner.rollback();
			}
			try (RepositoryConnection next = repository.getConnection()) {
				next.begin(IsolationLevels.SNAPSHOT);
				next.rollback();
			}
		} finally {
			awaitIfPresent(beginFuture);
			executor.shutdownNow();
			try {
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS),
						"the transaction-begin worker must terminate");
			} finally {
				repository.shutDown();
			}
		}
	}

	private static LmdbStore newStore(Path dataDirectory) {
		return new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(INITIAL_MAP_BYTES)
				.setValueDBSize(INITIAL_MAP_BYTES)
				.setAutoGrow(true)
				.setMapGrowthThreshold(0.10d)
				.setMapGrowthReadDrainTimeoutMillis(30_000L));
	}

	private static String growthNamespace() {
		int namespaceBytes = Math.toIntExact((long) Math.ceil(INITIAL_MAP_BYTES * 0.10d));
		return "urn:lmdb:none-admission:growth-demand:" + "n".repeat(namespaceBytes);
	}

	private static Query prepareQuery(RepositoryConnection connection, QueryKind kind) throws Exception {
		String select = "SELECT ?value WHERE { <" + SEED_SUBJECT + "> <" + SEED_PREDICATE + "> ?value }";
		String ask = "ASK { <" + SEED_SUBJECT + "> <" + SEED_PREDICATE + "> \"" + SEED_OBJECT + "\" }";
		String construct = "CONSTRUCT { ?subject ?predicate ?object } WHERE { ?subject ?predicate ?object }";
		return switch (kind) {
		case TUPLE -> connection.prepareTupleQuery(select);
		case BOOLEAN -> connection.prepareBooleanQuery(ask);
		case GRAPH -> connection.prepareGraphQuery(construct);
		};
	}

	private static boolean evaluateQuery(Query query) throws Exception {
		if (query instanceof TupleQuery tupleQuery) {
			try (TupleQueryResult result = tupleQuery.evaluate()) {
				return result.hasNext();
			}
		}
		if (query instanceof BooleanQuery booleanQuery) {
			return booleanQuery.evaluate();
		}
		if (query instanceof GraphQuery graphQuery) {
			try (GraphQueryResult result = graphQuery.evaluate()) {
				return result.hasNext();
			}
		}
		throw new IllegalArgumentException("Unsupported public query type: " + query.getClass().getName());
	}

	private static void awaitAdmissionWait(LmdbSailStore backing, long previousWaitCount,
			Future<?> query, String message) {
		long timeoutAt = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (true) {
			MapGrowthMetrics.Snapshot metrics = backing.growthMetricsSnapshot();
			if (metrics.currentAdmissionWaiters() > 0 || metrics.admissionWaitCount() > previousWaitCount) {
				return;
			}
			if (query.isDone()) {
				throw new AssertionError(message + "; the query finished without entering admission wait");
			}
			if (System.nanoTime() >= timeoutAt) {
				throw new AssertionError(message + "; the query never entered admission wait");
			}
			Thread.onSpinWait();
		}
	}

	private static void awaitPhase(LmdbSailStore backing, LmdbSailStore.GrowthPhase expected, String message) {
		long timeoutAt = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (backing.growthMetricsSnapshot().currentPhase() != expected) {
			if (System.nanoTime() >= timeoutAt) {
				throw new AssertionError(message + "; current phase was "
						+ backing.growthMetricsSnapshot().currentPhase());
			}
			Thread.onSpinWait();
		}
	}

	private static void awaitGrowthReopened(LmdbSailStore backing) {
		long timeoutAt = System.nanoTime() + TimeUnit.SECONDS.toNanos(WAIT_SECONDS);
		while (backing.growthAdmissionClosed()
				|| backing.growthMetricsSnapshot().currentPhase() != LmdbSailStore.GrowthPhase.OPEN) {
			if (System.nanoTime() >= timeoutAt) {
				throw new AssertionError("growth admission did not reopen after the NONE writer rolled back");
			}
			Thread.onSpinWait();
		}
	}

	private static void await(CountDownLatch latch, String message) throws InterruptedException {
		assertTrue(latch.await(20, TimeUnit.SECONDS), message);
	}

	private static void awaitIfPresent(Future<?> future) {
		if (future != null) {
			try {
				future.get(5, TimeUnit.SECONDS);
			} catch (ExecutionException | java.util.concurrent.TimeoutException ignored) {
				// Preserve the primary assertion while allowing released work to finish.
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private static Throwable rootCause(Throwable failure) {
		Throwable current = failure;
		while (current.getCause() != null && current.getCause() != current) {
			current = current.getCause();
		}
		return current;
	}

	private enum QueryKind {
		TUPLE,
		BOOLEAN,
		GRAPH
	}

	private record BeginAttempt(Throwable failure, boolean activeAfterBegin) {
	}
}
